head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.isExist = false;
scwin.vSEG_CHG_TP_CD = "04";
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// 세션정보를 얻기위한 함수사용
scwin.vBzProcsNo;
scwin.TR_JOB;
scwin.chbArr = ["1_1_1", "1_1_2", "1_2_1", "1_2_2", "1_2_3", "1_2_4", "2_1"];

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        const parentWin = $c.frame.path("../");
        if (parentWin.scwin.vScrenID === "ULDSTF05006.gfm" || parentWin.scwin.vScrenID === "ULDSTF05007.gfm") {
            // 신규상장에서 호출
            scwin.vBzProcsNo = parentWin.scwin.vBzProcsNo;
        } else {
            btn_Save.hide();
            btn_Delete.hide();
            const dstObj = parentWin.dts_List_2;
            const row = dstObj.getFocusedRowIndex();
            scwin.vBzProcsNo = dstObj.getCellData(row, "PRELM_INVSTG_BZ_PROCS_NO");
        }
        /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
        buttonSet.setSaveInfo(btn_Save, scwin.save); // 저장
        buttonSet.setDeleteInfo(btn_Delete, scwin.delete); // 삭제

        await scwin.condReadSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05814.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_Save_OnFail = function() {
    try {
        $c.lc.fn_alertMsg('F');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05814.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        $c.lc.fn_alertMsg('S');
        if (buttonSet.status === "D") {
            // 삭제처리의 응답인 경우
            await $c.win.closePopup();
        } else {
            await scwin.condReadSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05814.trs_Save_OnSuccess" });
    }
};

