///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name condReadSync
 * @description cond Read Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.condReadSync = async function() {
    url += "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    const sbmOptions = {
        id : "sbm_dts_Condition",
        action : "/SegmentChange.do",
        ref : "",
        target : "dts_Condition=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    if (dts_Condition.getRowCount() > 0) {
        scwin.isExist = true;
    }
    scwin.readCondDataSet();
};

/**
 * @method
 * @name trs
 * @description trs 처리
 * @param {*} jobType jobType
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs = async function(jobType) {
    let vScrenProcTpCd;
    if (scwin.TR_JOB === "I") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_02;
    } else if (scwin.TR_JOB === "U") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_03;
    } else if (scwin.TR_JOB === "D") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_04;
    }
    scwin.setCondition(jobType);
    trs_Save.KeyName = "toinb_dataid4";
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/SegmentChange.do",
        ref : "dts_newCondition",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    scwin.TR_JOB = 'I';
    if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
    await scwin.trs(TR_JOB_INSERT);
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    if (scwin.isExist) {
        scwin.TR_JOB = 'D';
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        buttonSet.setDeleteStatus();
        await scwin.trs(TR_JOB_DELETE);
    } else {
        await $c.win.alert("삭제할 데이터가 없습니다.");
    }
};

/**
 * @method
 * @name clickCheck
 * @description 충족 해당/미해당 체크박스 처리
 * @param {*} chkObj chkObj
 * @returns {void}
 * @hidden N
 */
scwin.clickCheck = function(chkObj) {
    const chkId = chkObj.id;
    let childChkId, repChildChkId;
    if (chkObj.checked === true) {
        // 체크되었을때만
        let repChkId;
        let repChkObj;
        if (chkId.indexOf("Y") > 1) {
            repChkId = chkId.replace("Y", "N");
        } else {
            repChkId = chkId.replace("N", "Y");
        }
        repChkObj = Number(repChkId);
        repChkObj.setValue("");
    }
};

/**
 * @method
 * @name setCondition
 * @description 충족요건 데이터셋 셋팅 처리
 * @param {*} jobType jobType
 * @returns {void}
 * @hidden N
 */
scwin.setCondition = function(jobType) {
    let chkYId, chkNId = "";
    let chkYObj, chkNObj;
    let condArr;
    let satisYn = "Y";
    // dts_newCondition.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
    dts_newCondition.setBroadcast(false);
    for (let i = 0, j = scwin.chbArr.length; i < j; i++) {
        chkYId = "chb_Y_" + scwin.chbArr[i];
        chkNId = "chb_N_" + scwin.chbArr[i];
        chkYObj = Number(chkYId);
        chkNObj = Number(chkNId);
        if (chkYObj.checked) {
            condArr = (chkYId.replace("chb_Y_", "")).split("_");
            scwin.setCondDataset(dts_newCondition, condArr, "Y");
        } else {
            condArr = (chkNId.replace("chb_N_", "")).split("_");
            scwin.setCondDataset(dts_newCondition, condArr, "N");
        }
        dts_newCondition.setCellData(i, "JOB_TYPE", jobType);
    }
    dts_newCondition.setBroadcast(true, true);
};

/**
 * @method
 * @name setCondDataset
 * @description 충족요건 데이터셋 설정
 * @param {*} dataSet dataSet
 * @param {*} condArr condArr
 * @param {String} satisYn satisYn
 * @returns {void}
 * @hidden N
 */
scwin.setCondDataset = function(dataSet, condArr, satisYn) {
    dataSet.AddRow();
    dataSet.setCellData(dataSet.getRowCount(), "BZ_PROCS_NO", scwin.vBzProcsNo);
    dataSet.setCellData(dataSet.getRowCount(), "SEQ", dataSet.getRowCount());
    dataSet.setCellData(dataSet.getRowCount(), "SEG_CHG_TP_CD", scwin.vSEG_CHG_TP_CD);
    dataSet.setCellData(dataSet.getRowCount(), "COND_SATISFACT_YN", satisYn);
    if (condArr.length === 2) {
        dataSet.setCellData(dataSet.getRowCount(), "UPCLSS_ID", condArr[0]);
        dataSet.setCellData(dataSet.getRowCount(), "MIDCLSS_ID", condArr[1]);
    } else {
        dataSet.setCellData(dataSet.getRowCount(), "UPCLSS_ID", condArr[0]);
        dataSet.setCellData(dataSet.getRowCount(), "MIDCLSS_ID", condArr[1]);
        dataSet.setCellData(dataSet.getRowCount(), "LWCLSS_ID", condArr[2]);
    }
};

/**
 * @method
 * @name readCondDataSet
 * @description read Cond Data Set 처리
 * @returns {void}
 * @hidden N
 */
scwin.readCondDataSet = function() {
    let upclssId, midclssId, lwClssId, satisYn;
    let chbId, chbObj;
    if (dts_Condition.getRowCount() > 0) {
        for (let i = 1, j = dts_Condition.getRowCount(); i <= j; i++) {
            upclssId = dts_Condition.getCellData(i, "UPCLSS_ID");
            midclssId = dts_Condition.getCellData(i, "MIDCLSS_ID");
            lwClssId = dts_Condition.getCellData(i, "LWCLSS_ID");
            satisYn = dts_Condition.getCellData(i, "COND_SATISFACT_YN");
            chbId = "chb_" + satisYn + "_" + upclssId + "_" + midclssId;
            if (lwClssId.length > 0) {
                chbId = chbId + "_" + lwClssId;
            }
            chbObj = Number(chbId);
            chbObj.setValue(1);
            if (satisYn === "Y") {
                chbObj = Number(chbId.replace("Y", "N"));
                chbObj.setValue("");
            } else {
                chbObj = Number(chbId.replace("N", "Y"));
                chbObj.setValue("");
            }
        }
    }
};
